import{_ as e,a as r,o as i,ag as a}from"./chunks/framework.C2qfZH9T.js";const m=JSON.parse(`{"title":"Type d'entrée d'attribut","description":"","frontmatter":{},"headers":[],"relativePath":"attribute/attribute-input.md","filePath":"attribute/attribute-input.md","lastUpdated":1782937842000}`),d={name:"attribute/attribute-input.md"};function s(u,t,n,o,l,p){return i(),r("div",null,t[0]||(t[0]=[a('<h1 id="type-d-entree-d-attribut" tabindex="-1">Type d&#39;entrée d&#39;attribut <a class="header-anchor" href="#type-d-entree-d-attribut" aria-label="Permalink to &quot;Type d&#39;entrée d&#39;attribut&quot;">​</a></h1><p>Les attributs peuvent avoir différents types d&#39;entrée qui déterminent non seulement la manière dont vous saisissez les valeurs de l&#39;attribut, mais également la manière dont les acheteurs peuvent sélectionner les attributs dans le cas des options ou saisir des valeurs.</p><p>Les attributs du produit sont un ensemble de caractéristiques qui définissent un produit particulier ou un groupe de biens. Cela signifie que la taille, la couleur, la saveur, le type d&#39;emballage, etc. constituent des attributs. Les attributs du produit ne concernent pas seulement la description générale d&#39;un produit, mais ils parlent de la valeur du produit qui le rend unique.</p><table tabindex="0"><thead><tr><th>Propriété</th><th>Descriptif</th></tr></thead><tbody><tr><td>Texte</td><td>Un champ de saisie sur une seule ligne pour le texte.</td></tr><tr><td>Zone de texte</td><td>Un champ de saisie sur plusieurs lignes pour saisir des paragraphes de texte, comme une description de produit.</td></tr><tr><td>Prix ​​</td><td>Ce type d&#39;entrée est utilisé pour créer des champs de prix qui s&#39;ajoutent aux attributs prédéfinis : Prix, Prix spécial, Prix de niveau et Coût.</td></tr><tr><td>Booléen</td><td>Affiche une liste déroulante avec les options prédéfinies Oui et Non.</td></tr><tr><td>Sélectionnez</td><td>Affiche une option pour sélectionner une valeur.</td></tr><tr><td>Sélection multiple</td><td>Affiche une liste déroulante de valeurs acceptant plusieurs sélections.</td></tr><tr><td>Dates</td><td>Affiche une valeur de date dans le format préféré.</td></tr><tr><td>Date Heure</td><td>Affiche une valeur de date et d&#39;heure dans le format et le fuseau horaire préférés.</td></tr><tr><td>Images</td><td>Ceci est utilisé pour afficher l&#39;image. L&#39;attribut image peut être exclu du navigateur multimédia de la vitrine.</td></tr><tr><td>Fichier</td><td>Les attributs de fichier sont un type de métadonnées qui décrivent et peuvent modifier le comportement des fichiers et/ou des répertoires d&#39;un système de fichiers.</td></tr><tr><td>Case à cocher</td><td>Il représente un état ou une option qui peut être basculé.</td></tr></tbody></table>',4)]))}const f=e(d,[["render",s]]);export{m as __pageData,f as default};
